func (p *provisioner) resolveFileSource(v cty.Value) error {
	p.files.source = ""
	p.files.content = ""
	p.files.deleteSource = false
	p.files.tempName = ""
	p.files.isDir = false
	p.files.bytesCopied = 0
	p.files.err = nil

	content := v.GetAttr("content")
	src := v.GetAttr("source")
	switch {
	case !content.IsNull():
		p.files.mode = "content"
		p.files.content = content.AsString()
		return p.writeContentTemp()
	case !src.IsNull():
		p.files.mode = "source"
		return p.expandHomeSource(src.AsString())
	default:
		p.files.err = errors.New("source and content cannot both be null")
		return p.files.err
	}
}

func (p *provisioner) writeContentTemp() error {
	file, err := ioutil.TempFile("", "tf-file-content")
