	if _, err = file.WriteString(p.files.content); err != nil {
		p.files.deleteSource = true
		p.files.source = file.Name()
		p.files.tempName = file.Name()
		p.files.err = err
		return err
	}
	p.files.source = file.Name()
	p.files.tempName = file.Name()
	p.files.deleteSource = true
	return nil
}

func (p *provisioner) expandHomeSource(src string) error {
