func runScripts(ctx context.Context, o provisioners.UIOutput, comm communicator.Communicator, scripts []io.ReadCloser) error {
	p := &provisioner{}
	retryCtx, cancel := context.WithTimeout(ctx, comm.Timeout())
	defer cancel()

	err := p.retryConnect(retryCtx, comm, o)
	if err != nil {
		return err
	}

	// Ensure the connection is closed once the work is done, whether that
	// happens because all scripts ran successfully, the provisioner was
	// stopped, or an error occurred. Disconnect must only happen once, since
	// both this function and the context below may reach that state.
	var disconnectOnce sync.Once
	disconnect := func() {
		disconnectOnce.Do(func() {
			if err := comm.Disconnect(); err != nil {
				log.Printf("[ERROR] error disconnecting communicator: %s", err)
			}
		})
	}

	// Wait for the context to end and then disconnect
	go func() {
		<-ctx.Done()
		disconnect()
	}()

	for _, script := range scripts {
		if err := p.executeRemoteScript(comm, o, script); err != nil {
			disconnect()
			return err
		}
	}

	disconnect()

	return nil
}

